"""Читаемые пояснения к машинным контрактам GSV; без изменения исходных фактов."""
import csv
import json
import re

def polish(root):
    def read(name): return json.loads((root/name).read_text())
    def save(name, data): (root/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    def spacing(value):
        if isinstance(value,dict): return {k:spacing(v) for k,v in value.items()}
        if isinstance(value,list): return [spacing(v) for v in value]
        if isinstance(value,str) and len(value)>35 and not value.startswith(('http','git:','/')):
            value=re.sub(r'([а-яёА-ЯЁ])([A-Za-z0-9])',r'\1 \2',value)
            value=re.sub(r'([A-Za-z0-9])([а-яёА-ЯЁ])',r'\1 \2',value)
            value=value.replace('см.required_outputs','см. required_outputs')
        return value
    c=read('case.json')
    c['authorship']={'author_model_commit':'dceadc98f9a293d7530cb7bc50ca4411a95aa4b6','git_author':'kiruha355','role':'Авторская панель и модель; факты, вычисления и сценарии сохраняются раздельно. Авторство конкретных заимствованных строк определяется их provenance, а не только автором последнего коммита.','research_package':'Локальное исследование GSV; новые денежные/choice модели не создавались.'}
    c['demand'].update(
        local='Аэропорт обслужил 1,064 млн пассажиров за 2025 год. Это прилёты и вылеты всех перевозчиков, без разделения на конечные поездки и пассажиров RW. Числитель прироста RW из этого итога не получается.',
        regional='Подвоз из Саратовской области и короткие пары GSV–KUF/VOG/GOJ требуют датированного сравнения с наземным транспортом. Эти рынки не отсеяны по расстоянию 500 км.',
        long_distance='SVX, OVB и SGC представлены в опубликованном предложении; NUX имеет историю RW. Спрос TJM, OMS, PEE и остальных непокрытых OD остаётся неизвестным.',
        international='EVN, BUS и TBS — разные рынки. AYT и HRG имеют чартерные программы. Международный агрегат и пассажиропоток EVN не подставляются как спрос TBS или как доступная RW выручка.',
        seasonality='Первичные летнее и зимнее объявления различают предложение по сезонам. Региональные месячные профили гостиничного и санаторного размещения дают контекст; они не приняты как сезонная калибровка авиационных OD.',
        segments={'tourism':'Курортные направления и чартеры подтверждают предложение для отдыха. Маршрутные количества и доли туристов неизвестны.','business':'Деловой OD, корпоративные контракты и календарь командировок неизвестны; пригодность частот для короткой поездки проверяет P05.','family':'Доля семейных и VFR поездок неизвестна. География EVN, TBS или NUX не заменяет измерение цели поездки.','contract':'Ни одного договора блока кресел, гарантированного спроса или минимального платежа не введено.'})
    c['competitors'].update(
        connection_products='Пересадки через SVO, OVB, SVX и другие узлы нужно подтвердить конкретными продаваемыми продуктами. Из наличия рейсов на карте не получается единый билет.',
        price='Реклама RW «от 4000» на SVX–GSV с поисковой ссылкой туда–обратно не подтверждает односторонний окончательный тариф с 20 кг багажа. Наблюдаемые retail baskets пока отсутствуют.',
        response='Существующие продукты DP, SU, S7, UT и Shirak подтверждают присутствие в конечном источнике. Фактический оператор, свободный борт и величина ценовой/частотной реакции неизвестны. Применяется общая политика P05; произвольные проценты ответа не вводились.')
    c['operations'].update(
        airport='Приём RRJ95, H24, ВПП 3000×45 м и 21 стоянка опубликованы. Точный допуск SJ100/ПД-8, свободные слоты, ночная база, доступ RW к ТО и условия на даты 2027–2028 неизвестны.',
        disruption='Банк зависит от одного аэропорта. Для сравнения нужны фактические длительности ограничений, переносы, запасные аэропорты и стоимость восстановления. Дни публикаций о «Ковре» не равны часам простоя.')
    c['comparison_priority']=['CR-GSV-01/02: продажа и ресурс опубликованного коридора','CR-GSV-05: история северных продаж и текущий KEEP','CR-GSV-03/04: база и банк против применения того же ресурса из существующего опорного аэропорта','CR-GSV-07/08/09: договоры и почасовая пригодность аэропорта для финалистов']
    c['stopping_and_revisit']='Принятый операционный допуск — обязательное условие запуска. Денежное решение требует полной дельты к будущему KEEP, финансирования до прибыли и обязательств при выходе. Порог рассчитывает общее ядро, дата окупаемости при недостающих входах UNKNOWN. Неудача конкретного шаблона ведёт к проверке другой частоты/расписания в том же ресурсе; это не отказ от всех программ GSV.'
    c['national_work_boundary']='Поставки, налоги и общие правила не исследовались повторно: используются закреплённые P03/P04. RRJ95 и SJ100/ПД-8 раздельны; во всех предложенных опытах новых Ту-214 ноль. Git, публичный Site и панель автора не изменены.'
    save('case.json',spacing(c))
    h=read('hypotheses.json')
    descriptions={
        'H-GSV-01':('Согласованные расписания с 23 декабря дают 175 и 160 минут между четырьмя плечами RW. Наличие коммерческой защиты неизвестно.','На тех же креслах единый продукт может изменить выбор конечного OD; защита добавляет расходы и может вытеснить местные продажи.','Те же четыре рейса в фактическом будущем KEEP с текущим состоянием продажи; дополнительный прямой SVX–TBS на том же ресурсе.','Проверить sellability и правила; связать каждый из двух сегментов с inventory; затем сравнить цену, spill, свои потери, полную дельту и денежный поток. P03 отдельно связывает tail и экипажи.'),
        'H-GSV-02':('Есть местный аэропортовый поток, опубликованный SVX и сезонные южные направления. Свободный ресурс RW и договор базы не доказаны.','Местная база даёт выбор времени и нескольких прямых OD; добавляются расходы базы, смен, ТО, ввода и выхода.','Дополнительные прямые из SVX и лучшее доступное применение одного такого же борта в существующей базе при сохранённом KEEP.','На общей калибровке проверить 3/2/2 рейса, другие частоты, сезоны, отсутствие скидки/субсидии и стоимость базы; не подбирать спрос под прибыль.'),
        'H-GSV-03':('GSV расположен между восточными и южными пунктами; есть местные рынки. Защищённые внутренние пересадки и часовая мощность банка не установлены.','Местные и пересадочные поездки используют общие места. Дополнительный сегмент, ожидание, нарушения стыковок и собственные прямые продукты создают потери.','Те же спицы и два борта без transfer products; отдельно два таких же борта в SVX с прямыми продуктами на объединении рынков.','Сначала изолировать эффект защиты на одинаковых flight IDs, затем оптимизировать часы и ресурс. Вычесть displaced local и собственные direct/connecting продажи, рассчитать риск и cash.'),
        'H-GSV-04':('Первичный источник подтверждает запуск RW GSV–NUX 3 мая 2025 до двух раз в неделю. Текущая непрерывность и договорный спрос неизвестны.','Прямой локальный продукт может использовать общую группу SVX. История полётов обосновывает исследование; нефтегазовая география не даёт гарантированного блока кресел.','Текущий северный KEEP, опубликованные UT–SGC и продаваемые пересадки; прямой SVX–NUX на том же ресурсе.','Восстановить свои продажи и yield по месяцам/направлениям. Сопоставить четыре плеча через GSV с прямой альтернативой, ресурсом crew/ТО, зимой и летом без вымышленного корпоративного договора.'),
        'H-GSV-05':('BUS летом и TBS зимой подтверждены первичными источниками. Одна недельная частота ограничивает выбор длительности поездки.','Дополнительная суббота допускает поездки 3–4 ночи и может объединить местный и сквозной спрос. BUS и TBS не один OD и не один сезонный продукт.','Будущий KEEP с одной частотой и дополнительный прямой из SVX при том же ресурсе; во всех ветвях ноль новых Ту-214.','P05 проверяет длительность поездок, полные цены/багаж/lead и собственный переток; P03 — международный dispatch и crew; P04 — полный результат и cash.'),
        'H-GSV-06':('Есть опубликованные 80 минут автобуса и 46 минут поезда до аэропорта; ранние/поздние окна и остальная первая/последняя миля ограничены.','Подвоз может улучшить доступ к имеющимся рейсам и обойтись дешевле отдельного короткого авиаплеча. Это измеряется по полному времени и затратам договора.','Текущий подвоз и отдельный короткий авиаподвоз GSV–KUF/VOG на том же общем пуле OD.','Сравнить датированные door-to-door время, ожидание, цену, защиту и накладные расходы. Не считать население спросом и партнёрских пассажиров собственными сегментами RW.'),
        'H-GSV-07':('Доступны местные тарифы и положение скидок с 1 августа 2026. Условия RW и продление льготы оформления следующего посадочного талона неизвестны.','Скидка уменьшает часть аэропортового счёта. Она не создаёт спрос и не отменяет топливо, самолёт, экипажи и ТО.','Один принятый набор рейсов без скидки и с документально применимыми скидками на конкретные события.','P04 связывает договор, eligibility, счета, billed drivers и cash. Вывести необходимый порог поддержки и проверить достижимость; будущие неподтверждённые льготы остаются UNKNOWN.'),
        'H-GSV-08':('Источники показывают присутствие RW и маршруты. Приём RRJ95, H24 и 21 стоянка не подтверждают постоянную базу.','Корректная роль предотвращает бесплатное приписывание экипажей, ТО, стоянки и ошибочный исходный KEEP.','Обслуживаемый аэропорт и возможный сквозной коридор; новая база — самостоятельный проект.','Пересмотреть классификацию после договора/официального подтверждения базирования и датированных ночёвок tail, crew и доступа к ТО. Экономические варианты города остаются открытыми.')}
    for item in h['hypotheses']:
        signal,mechanism,cf,test=descriptions[item['hypothesis_id']]
        item.update(signal=signal,mechanism=mechanism,counterfactual=cf,distinguishing_test=test)
    h['registry_policy']='Все восемь гипотез имеют исход и условие пересмотра. Конкуренция, расстояние 500 км и UNKNOWN не обозначают экономического отказа.'
    save('hypotheses.json',spacing(h))
    r=read('readiness.json')
    r.update(stage_A_scope='Местные источники и роль RW; конкуренция и пробелы; эксплуатация и тарифы; восемь гипотез; девять программ и контролей; помесячный размер шаблонов и парные запросы Stage B.',
        actual_current_fare_baskets='Не наблюдались; неизвестные цены не превращены в ноль.',
        P06_run='NOT_RUN: прочитан закреплённый producer contract; полного принятого bundle нет.',
        completed_independent_of_P05=['Локальные первичные источники и история','Расписание коридора и проверка местных часов','Справочные местные тарифные drivers и эксплуатационные пробелы','Гипотезы, частоты, альтернативные allocations и 24 месяца шаблонов','Hashes источников и исходных строк, output manifest'],
        not_done_and_not_rejected=['Датированные сопоставимые цены с 20 кг багажа во всех сезонах и проверка сквозной продажи','Принятая общая калибровка OD/choice на 2027–2028','Полные tail, crew, MRO, reserve и будущий KEEP','Договоры базы, топлива, скидок, ввода и выхода','Общий расчёт P06 экономики, финансирования и всех альтернатив'],
        external_effects='Открытый search/HTTP и разрешённый handoff координатору. Нет сообщений третьим лицам, брони, платежей, перезапусков или Git-изменений.')
    save('readiness.json',spacing(r))
    x=read('handoff.json')
    x.update(git_operations='Только read-only Git; завершённый пакет коммитит координатор.',
        early_usable_findings=['Согласованный коридор SVX–GSV–TBS с 23 декабря, интервалы 175/160 минут; коммерческая защита и tail binding неизвестны.','535 минут расписательных блоков и 920 минут всей цепочки: одна обычная непрерывная crew смена не обоснована.','История RW GSV–NUX с мая 2025 до двух раз в неделю; текущий KEEP и спрос требуют восстановления.','17 справочных местных ставок из версии 1 ноября; версия 16 ноября отдельно; договорные скидки и продление льгот неизвестны.'],
        integration_contract=['Взять кандидаты для одного контролируемого опыта; не складывать их пассажиров и деньги.','Связать P02/P03/P05/P04 в P06 по датированным flight, demand_pool, shared_event и KEEP.','Первыми закрыть CR-GSV-01/02/05/07; остальные запросы перечислены без скрытого отсева.','Stage A — завершённое местное исследование и конструирование, а не принятая экономика или доказательство достижения №2.'],
        source_of_truth='URL, fetch receipts, exact Git pins, исходные row IDs/hashes. Полные чужие fixtures и архивы не копировались.',
        finance='Финансовый победитель, финансирование до прибыли и дата окупаемости неизвестны до Stage B. Спрос, расходы и поддержка не подбирались к положительному результату.',
        evidence_boundaries=r['not_done_and_not_rejected'])
    save('handoff.json',spacing(x))
    save('programme_candidates.json',spacing(read('programme_candidates.json')))
    # Разделяем слипшиеся обозначения в пояснениях CSV; идентификаторы и исходные строки не переписываются.
    for name in ['comparison_requests.csv','market_deltas.csv','assumptions.csv','monthly_design_footprint.csv']:
        with (root/name).open() as f: items=list(csv.DictReader(f))
        for item in items:
            for key in list(item):
                if key not in {'source_id','programme_id','programme_ids','request_id','assumption_id','delta_id','source_url','source_sha256'}:
                    item[key]=spacing(item[key])
        with (root/name).open('w',newline='') as f:
            w=csv.DictWriter(f,fieldnames=items[0].keys());w.writeheader();w.writerows(items)
    with (root/'evidence.csv').open() as f: items=list(csv.DictReader(f))
    organisations={'GSV-MK2025':'МК в Саратове; пересказ ответа Минтранса Саратовской области','GSV-RAILSVX':'Яндекс Расписания; расписательный агрегатор','GSV-AVV-NEWS':'АО «Саратовское объединение автовокзалов и автостанций»','PIN-dceadc98-catchments':'Авторская модель kiruha355; население ВПН-2021 и внешний источник транспортной связности','PIN-dceadc98-primary_seasonality_profiles':'Командная производная таблица из Росстата/ЕМИСС; provenance через exact dceadc98','PIN-d9486f11-city_coverage':'Исследовательский пакет P02v2, exact d9486f11','PIN-dceadc98-rw_routes_now':'Авторский вход kiruha355 по опубликованному плану Росавиации; exact dceadc98'}
    for item in items:
        if item['source_id'] in organisations:item['organisation']=organisations[item['source_id']]
        item['underlying_primary_url']='https://www.fedstat.ru/indicator/62073' if item['evidence_id']=='E-GSV-27' else ''
        item['source_live_verification']='Повторная live-проверка определения ряда не получена; используется только сохранённый региональный контекст.' if item['evidence_id']=='E-GSV-27' else 'См. status, fetch_receipts и exact source pins.'
    with (root/'evidence.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=items[0].keys());w.writeheader();w.writerows(items)
